function assistantView(){return '<div class="ai2-module-head"><div><h1>Assistant ArtisanIA</h1><p class="muted">Décris ce que tu veux noter ou organiser. L’assistant retrouve le contexte et prépare une proposition à vérifier.</p></div><span class="pill blue">Cerveau local V3</span></div><div class="card ai2-brain-compose"><label class="lbl" for="ai2-command">Que veux-tu dire à ArtisanIA ?</label><textarea id="ai2-command" rows="4" placeholder="Ex. : Rappelle-moi d’appeler M. Dupont demain pour son chantier de toiture."></textarea><div class="row" style="margin-top:12px"><button class="btn primary" id="ai2-run">Analyser ma demande</button><span class="muted small">Aucune action ne sera effectuée sans ta confirmation.</span></div></div><div id="ai2-result" class="ai2-brain-result" aria-live="polite"></div><div class="card" style="margin-top:14px"><h2>Comment fonctionne le cerveau ?</h2><p class="muted">ArtisanIA analyse la phrase localement, recherche les fiches correspondantes dans la mémoire de l’entreprise et prépare une action. Les noms ambigus doivent être précisés. Aucune donnée n’est modifiée pendant l’analyse.</p></div>'}
let pendingBrainProposal=null;
function brainNormalize(value){return String(value??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[’']/g,' ').replace(/\brapel\b/g,'rappel').replace(/\bapeller\b|\bappeller\b|\bapeler\b/g,'appeler').replace(/\bveriffier\b/g,'verifier').replace(/[^a-z0-9€.,!?\s-]/g,' ').replace(/-/g,' ').replace(/\s+/g,' ').trim()}
function brainMemory(){
 const key='artisania.brain.memory.v1';let memory;
 try{memory=JSON.parse(localStorage.getItem(key)||'null')}catch(e){throw new Error('La mémoire locale existe mais elle est illisible. Aucune donnée n’a été modifiée.')}
 if(memory&&memory.version!==1)throw new Error('La version de la mémoire locale n’est pas reconnue. Aucune donnée n’a été modifiée.');
 if(!memory)memory={version:1,entities:[],updatedAt:null};
 if(!Array.isArray(memory.entities))throw new Error('La structure de mémoire est invalide. Aucune donnée n’a été modifiée.');
 const map=[['clients','client'],['prospects','prospect'],['jobs','job'],['tasks','task'],['suppliers','supplier'],['materials','material'],['events','event'],['notes','note'],['invoices','invoice'],['expenses','expense']];
 const known=new Set(memory.entities.map(x=>x.id));let added=0;
 const makeId=(type,id)=>'memory:'+type+':'+encodeURIComponent(String(id));
 for(const [collection,type] of map){for(const record of db[collection]||[]){if(!record||record.id==null)continue;const id=makeId(type,record.id);if(known.has(id))continue;memory.entities.push({id,type,sourceId:String(record.id),data:JSON.parse(JSON.stringify(record)),createdAt:null,updatedAt:new Date().toISOString(),source:'migration:artisania.business.v2',confidence:1,links:[],status:'confirmed'});known.add(id);added++;}}
 const bySource=(type,id)=>memory.entities.find(x=>x.type===type&&String(x.sourceId)===String(id));
 for(const entity of memory.entities){if(entity.source!=='migration:artisania.business.v2'||entity.links?.length)continue;const d=entity.data||{};const client=(d.clientId&&bySource('client',d.clientId))||((d.client)&&memory.entities.filter(x=>x.type==='client'&&brainNormalize(x.data?.name)===brainNormalize(d.client)).length===1?memory.entities.find(x=>x.type==='client'&&brainNormalize(x.data?.name)===brainNormalize(d.client)):null);const job=(d.jobId&&bySource('job',d.jobId))||((d.job)&&memory.entities.filter(x=>x.type==='job'&&brainNormalize(x.data?.title)===brainNormalize(d.job)).length===1?memory.entities.find(x=>x.type==='job'&&brainNormalize(x.data?.title)===brainNormalize(d.job)):null);if(entity.type==='job'&&client)entity.links.push({type:'client',id:client.id});if(['task','event','note','invoice'].includes(entity.type)){if(client)entity.links.push({type:'client',id:client.id});if(job)entity.links.push({type:'job',id:job.id});}}
 if(added||!localStorage.getItem(key)){memory.updatedAt=new Date().toISOString();localStorage.setItem(key,JSON.stringify(memory));}
 return memory;
}
function brainResolve(memory,message){
 const entities=memory.entities||[];const candidates=entities.filter(x=>['client','prospect','job','supplier'].includes(x.type)&&x.status!=='archived');
 const matches=candidates.filter(x=>{const label=x.type==='job'?x.data?.title:x.data?.name;const phrase=brainNormalize(label);return phrase.length>=3&&(' '+brainNormalize(message)+' ').includes(' '+phrase+' ')});
 const grouped=new Map();for(const entity of matches){const label=brainNormalize(entity.type==='job'?entity.data?.title:entity.data?.name);const k=entity.type+':'+label;if(!grouped.has(k))grouped.set(k,[]);grouped.get(k).push(entity)}
 const selected=[],ambiguous=[];for(const group of grouped.values()){if(group.length===1)selected.push(group[0]);else ambiguous.push(group)}
 return {matched:selected,ambiguous};
}
function brainDate(raw){const t=brainNormalize(raw);const m=raw.match(/\b(20\d{2}-\d{2}-\d{2})\b/);if(m)return m[1];const d=new Date();if(t.includes('demain'))d.setDate(d.getDate()+1);else if(t.includes('aujourd hui')){}else return '';return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function brainShow(html){$('#ai2-result',root).innerHTML=html}
function brainExtractActions(raw){
 let text=brainNormalize(raw).replace(/^\s*(demain|aujourd hui|20\d{2}-\d{2}-\d{2})\s*[,;:.-]?\s*/i,'').replace(/^\s*(rappel moi|rappeler|pense a|ne pas oublier|je dois|il faut(?: que je)?)\s*/i,'').replace(/^\s*(de|d)\s*/i,'').replace(/\s+(demain|aujourd hui|20\d{2}-\d{2}-\d{2})\s*.*$/i,'').replace(/[.!?]+$/,'').trim();
 const m=text.match(/^(.+?)\s+pour\s+(.+)$/i);let parts=m?[m[1],...m[2].split(/\s+et\s+/i)]:[text];
 return parts.map(x=>String(x).trim().replace(/^(?:de|d)\s*/i,'')).filter(Boolean).map(x=>x.charAt(0).toLocaleUpperCase('fr')+x.slice(1));
}
function runCommand(){
 const raw=$('#ai2-command',root)?.value.trim();if(!raw)return;pendingBrainProposal=null;
 let memory;try{memory=brainMemory()}catch(error){brainShow('<div class="banner warn">'+esc(error.message)+'</div>');return}
 const normalized=brainNormalize(raw);
 const rules=[{intent:'reminder',re:/\b(rappelle moi|rappeler|ne pas oublier|pense a|je dois (?:appeler|contacter|verifier|faire le point)|il faut que je (?:appelle|contacte|verifie))\b/,label:'Préparer un rappel'},{intent:'follow_up',re:/\b(relancer|relance|recontacter)\b/,label:'Préparer une relance'},{intent:'schedule',re:/\b(rendez vous|rdv|visite)\b/,label:'Rendez-vous détecté'},{intent:'delivery',re:/\b(livre|livraison|livrer|arrive)\b/,label:'Information de livraison détectée'},{intent:'payment_received',re:/\b(recu|recois|acompte|paiement|paye)\b/,label:'Information de paiement détectée'},{intent:'job_update',re:/\b(chantier|commence|demarre|termine|avance)\b/,label:'Information de chantier détectée'}];
 const rule=rules.find(x=>x.re.test(normalized));if(!rule){brainShow('<div class="card"><h2>Je n’ai pas encore identifié l’action</h2><p class="muted">Essaie : « Rappelle-moi d’appeler M. Dupont demain ».</p></div>');return}
 if(!['reminder','follow_up'].includes(rule.intent)){brainShow('<div class="card"><h2>'+esc(rule.label)+'</h2><p class="muted">Ce type d’action sera pris en charge progressivement par le cerveau V3.</p></div>');return}
 const date=brainDate(raw);if(!date){brainShow('<div class="card"><h2>Il me manque une date</h2><p class="muted">Indique une date, par exemple « demain » ou « 2026-12-01 ».</p></div>');return}
 const query=brainNormalize(raw);const candidates=(memory.entities||[]).filter(x=>['client','job'].includes(x.type)&&x.status!=='archived'&&x.data).sort((x,y)=>{const lx=brainNormalize(x.type==='job'?x.data.title:x.data.name),ly=brainNormalize(y.type==='job'?y.data.title:y.data.name);const rx=lx&&query.includes(lx)?0:1,ry=ly&&query.includes(ly)?0:1;return rx-ry||String(x.data.name||x.data.title||'').localeCompare(String(y.data.name||y.data.title||''),'fr')});
 const actions=brainExtractActions(raw);
 pendingBrainProposal={data:{id:uid(),title:'Tâche à organiser',date,status:'À faire',priority:/urgent/i.test(normalized)?'Urgente':'Normale',client:'',clientId:'',job:'',jobId:'',actions:actions.map(title=>({id:uid(),title,date,time:'',status:'À faire'}))},candidates,selected:null};
 const choices=candidates.map(x=>{const label=x.type==='job'?x.data.title:x.data.name;const detail=x.type==='job'?(x.data.client||'Chantier'):[x.data.address,x.data.phone].filter(Boolean).join(' · ');return '<label class="ai2-brain-choice"><input type="radio" name="ai2-target" value="'+esc(x.type+':'+x.id)+'"><span><strong>'+esc(label||'Fiche sans nom')+'</strong><small class="muted">'+(x.type==='job'?'Chantier':'Client')+(detail?' · '+esc(detail):'')+'</small></span></label>'}).join('');
 const sub=actions.map(x=>'<li>'+esc(x)+'</li>').join('');
 brainShow('<div class="card ai2-brain-proposal"><div class="row" style="justify-content:space-between"><h2>Voici ce que j’ai compris</h2><span class="pill warn">À confirmer</span></div><p><strong>'+esc(rule.label)+'</strong></p><p><strong>Date :</strong> '+esc(new Date(date+'T12:00:00').toLocaleDateString('fr-FR',{day:'numeric',month:'long',year:'numeric'}))+'</p><h3>Client ou chantier à associer</h3><p class="muted small">Sélectionne la bonne fiche. Aucune association n’est faite automatiquement.</p><div class="ai2-brain-choices">'+(choices||'<p class="muted">Aucun client ou chantier enregistré.</p>')+'<label class="ai2-brain-choice"><input type="radio" name="ai2-target" value="none"><span><strong>Sans association</strong></span></label></div><p id="ai2-selected" class="muted small">Aucune fiche sélectionnée.</p><h3>Actions à réaliser</h3><ul>'+sub+'</ul><p class="muted small">Chaque action pourra avoir son propre horaire. Aucune tâche n’a encore été créée.</p><div class="row" style="margin-top:14px"><button class="btn primary" id="ai2-confirm" disabled>Confirmer et créer la tâche</button><button class="btn" id="ai2-reject">Annuler</button></div></div>');
 root.querySelectorAll('[name="ai2-target"]').forEach(input=>input.onchange=()=>{const p=pendingBrainProposal,v=input.value;p.selected=v;if(v==='none'){p.data.title='Tâche sans client';}else{const [type,...parts]=v.split(':');const x=p.candidates.find(e=>e.type===type&&e.id===parts.join(':'));if(!x)return;if(type==='client'){p.data.client=x.data.name||'';p.data.clientId=x.sourceId||'';p.data.title=p.data.client+' — Suivi';}else{p.data.job=x.data.title||'';p.data.jobId=x.sourceId||'';p.data.title=(x.data.client||'Chantier')+' — Suivi';const c=x.links?.map(l=>memory.entities.find(e=>e.id===l.id)).find(e=>e?.type==='client');if(c){p.data.client=c.data.name||'';p.data.clientId=c.sourceId||'';}}}const chosen=p.candidates.find(x=>v===x.type+':'+x.id);$('#ai2-selected',root).textContent=v==='none'?'Aucune association':chosen?(chosen.type==='job'?'Chantier : ':'Client : ')+(chosen.type==='job'?chosen.data.title:chosen.data.name):'';$('#ai2-confirm',root).disabled=false;});
 $('#ai2-confirm',root).onclick=()=>{if(!pendingBrainProposal?.selected)return;const p=pendingBrainProposal,before=JSON.stringify(db.tasks);db.tasks.unshift(p.data);if(!save()){db.tasks=JSON.parse(before);return}pendingBrainProposal=null;brainShow('<div class="banner good">La tâche et ses actions ont été créées. Tu peux les retrouver dans l’onglet Tâches.</div>');};
 $('#ai2-reject',root).onclick=()=>{pendingBrainProposal=null;brainShow('<div class="banner">Proposition annulée. Aucune donnée métier n’a été modifiée.</div>')};
}
function section(title,type,placeholder,key,fields){const arr=db[{client:'clients',prospect:'prospects',job:'jobs',task:'tasks',supplier:'suppliers',material:'materials',event:'events',note:'notes',invoice:'invoices',expense:'expenses'}[type]];return '<div class="ai2-module-head"><div><h1>'+title+'</h1><p class="muted">'+arr.length+' élément(s) enregistré(s) · données partagées dans l’espace entreprise</p></div><button class="btn primary ai2-add-btn" data-new="'+type+'">＋ Ajouter</button></div><div class="card ai2-list-panel"><div class="ai2-search-row"><input class="search" id="ai2-search" placeholder="Rechercher dans '+title.toLowerCase()+'…" aria-label="Rechercher dans '+title+'"><span class="muted" id="ai2-search-count">'+arr.length+' résultat(s)</span></div><div id="ai2-list">'+list(type,arr,{title:key,sub:fields[1]})+'</div></div>'}
const labels={number:'N° de facture',invoiceDate:'Date de facture',dueDate:'Échéance',amount:'Montant (€)',name:'Nom',address:'Adresse',phone:'Téléphone',email:'E-mail',notes:'Notes',origin:'Origine',need:'Besoin exprimé',status:'Statut',nextDate:'Prochaine relance',title:'Intitulé',client:'Client associé',start:'Début prévu',end:'Fin prévue',date:'Date',priority:'Priorité',job:'Chantier associé',category:'Catégorie',contact:'Contact',website:'Site internet',terms:'Conditions / tarifs',reference:'Référence',unit:'Unité',price:'Prix unitaire (€)',supplier:'Fournisseur',updated:'Date de mise à jour',time:'Heure',place:'Lieu',content:'Contenu'};
const schemas={
client:['name','address','phone','email','notes'],prospect:['name','phone','email','origin','need','status','nextDate','notes'],job:['title','client','address','status','start','end','notes'],task:['title','date','priority','status','client','job','notes'],supplier:['name','category','contact','phone','email','website','terms','notes'],material:['name','reference','category','unit','price','supplier','updated','notes'],event:['title','date','time','place','client','job','notes'],note:['title','date','client','job','content'],invoice:['number','client','invoiceDate','dueDate','amount','status','notes'],expense:['title','supplier','date','category','amount','status','notes']};
function linkExistingClientReferences(){let changed=false;const collections=[db.jobs,db.tasks,db.events,db.notes,db.invoices];for(const items of collections){for(const item of items){if(item.clientId)continue;const name=String(item.client||'').trim().toLocaleLowerCase('fr');if(!name)continue;const client=db.clients.find(x=>String(x.name||'').trim().toLocaleLowerCase('fr')===name);if(client){item.clientId=client.id;changed=true}}}if(changed)save();return changed}
function syncClientReferences(client,previous){const oldName=String(previous?.name||'').trim().toLocaleLowerCase('fr');const oldAddress=String(previous?.address||'').trim();for(const items of [db.jobs,db.tasks,db.events,db.notes,db.invoices]){for(const item of items){const matches=(client.id&&String(item.clientId||'')===String(client.id))||(!item.clientId&&oldName&&String(item.client||'').trim().toLocaleLowerCase('fr')===oldName);if(!matches)continue;item.clientId=client.id;item.client=client.name||'';if(items===db.jobs&&oldAddress&&String(item.address||'').trim()===oldAddress)item.address=client.address||''}}}
function syncJobClientReferences(job,previous){const client=db.clients.find(x=>String(x.id)===String(job.clientId||''));if(!client||!previous)return;const oldJobAddress=String(previous.address||'').trim();const oldClientAddress=String(client.address||'').trim();if(oldJobAddress===oldClientAddress&&String(job.address??'').trim()!==oldJobAddress)client.address=String(job.address??'').trim();}
function attachClientReference(type,target){if(!['job','task','event','note','invoice'].includes(type))return;const name=String(target.client||'').trim();const client=db.clients.find(x=>String(x.name||'').trim().toLocaleLowerCase('fr')===name.toLocaleLowerCase('fr'));if(client)target.clientId=client.id;else delete target.clientId}
